CREATE INDEX active_claim_end ON recipient_schedule(claim_until_ms) WHERE claim_token IS NOT NULL;
CREATE INDEX actor_submissions ON submissions(actor_id,seq);
CREATE INDEX actor_workspaces ON workspace_members(actor_id,workspace_id);
CREATE INDEX done_topics_of ON pipeline_done_topics(workspace_id, topic_id);
CREATE INDEX due_recipients ON recipient_schedule(next_due_ms,recipient_id) WHERE enabled=1 AND pending_count>0;
CREATE INDEX editor_submissions ON submissions(actor_id,source_key,topic_id,seq);
CREATE INDEX eligible_groups ON delivery_groups(recipient_id,id) WHERE active=1 AND pending_count>0;
CREATE INDEX eligible_heads ON delivery_groups(recipient_id,first_pending_seq) WHERE active=1 AND pending_count>0;
CREATE INDEX held_stage_asks ON pipeline_stage_entries(ask_message_id) WHERE ask_message_id IS NOT NULL AND left_ms IS NULL;
CREATE INDEX held_target_asks ON outcome_target_revisions(ask_message_id) WHERE outcome IS NULL;
CREATE INDEX hosted_turns_open ON hosted_turns(thread_id,turn_id) WHERE final_status IS NULL;
CREATE INDEX hosted_turns_turn ON hosted_turns(thread_id,turn_id,final_status);
CREATE INDEX item_events ON pipeline_events(workspace_id, number, seq DESC);
CREATE INDEX item_pieces ON pipeline_piece_members(workspace_id, number, piece_id);
CREATE INDEX item_takes ON conversation_takes(item_id,id);
CREATE INDEX message_reaction_rows ON message_reactions(message_id);
CREATE INDEX message_reply_links ON messages(reply_to,seq) WHERE reply_to IS NOT NULL;
CREATE INDEX open_conversation_items ON conversation_items(message_id) WHERE settled = 0;
CREATE INDEX open_entries ON pipeline_stage_entries(workspace_id, piece_id) WHERE left_ms IS NULL;
CREATE INDEX open_openings ON openings(actor_id,workspace_id,id) WHERE state='open';
CREATE INDEX owned_media ON media_intents(actor_id,id);
CREATE INDEX participant_topics ON topic_participants(actor_id,active,topic_id);
CREATE INDEX pending_group_deliveries ON deliveries(group_id,seq) WHERE state='pending';
CREATE INDEX pending_group_topic_deliveries ON deliveries(group_id,topic_id,seq) WHERE state='pending';
CREATE INDEX piece_entries ON pipeline_stage_entries(piece_id, seq);
CREATE INDEX pipeline_fact_order ON pipeline_facts(workspace_id, seq);
CREATE INDEX pipeline_order ON pipeline_items(workspace_id, section, candidate_group, position, number);
CREATE INDEX pipeline_recent ON pipeline_events(workspace_id, seq DESC);
CREATE INDEX problems_by_time ON found_problems(workspace_id, found_ms DESC);
CREATE INDEX reader_marks ON message_marks(actor_id,topic_id,seq) WHERE revision%2=1;
CREATE INDEX reader_waiting ON topic_waiting(actor_id,archived,state_ms DESC,topic_id);
CREATE INDEX readings_by_check ON check_readings(workspace_id, check_id, run_id);
CREATE INDEX readings_by_piece ON check_readings(piece_id, check_id, run_id) WHERE piece_id IS NOT NULL;
CREATE INDEX recipient_deliveries ON deliveries(recipient_id,state,seq);
CREATE INDEX runner_attempts ON wake_attempts(runner_token,started_ms);
CREATE INDEX runs_base ON check_runs(workspace_id, base_for_commit) WHERE base_for_commit IS NOT NULL;
CREATE INDEX runs_by_commit ON check_runs(workspace_id, commit_sha, started_ms DESC);
CREATE INDEX runs_by_time ON check_runs(workspace_id, started_ms DESC);
CREATE INDEX runs_trials ON check_runs(workspace_id, trial_of) WHERE trial_of IS NOT NULL;
CREATE INDEX scoped_changes ON changes(scope_kind,scope_id,seq);
CREATE INDEX scoped_memory_items ON memory_items(scope_kind,scope_id,seq);
CREATE INDEX stage_history ON pipeline_stage_entries(workspace_id, stage_id, size, round > 1, left_ms DESC) WHERE left_ms IS NOT NULL;
CREATE INDEX subject_ref ON message_subjects(workspace_id, kind, ref, message_id);
CREATE INDEX topic_messages ON messages(topic_id,seq);
CREATE INDEX topic_sources ON topics(source_message_id,id) WHERE source_message_id IS NOT NULL;
CREATE INDEX unaddressed_messages ON messages(topic_id,seq) WHERE addressees='[]';
CREATE INDEX workspace_topic_order ON topics(workspace_id,archived,state='done',activity_ms DESC,id DESC);
CREATE INDEX workspace_topics ON topics(workspace_id,id);
CREATE TABLE actors (id TEXT PRIMARY KEY, kind TEXT NOT NULL, name TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE changes (seq INTEGER PRIMARY KEY AUTOINCREMENT, scope_kind TEXT NOT NULL, scope_id TEXT NOT NULL, resource_kind TEXT NOT NULL, resource_id TEXT NOT NULL, version INTEGER NOT NULL);
CREATE TABLE check_allowances (workspace_id TEXT NOT NULL REFERENCES workspaces(id), check_id TEXT NOT NULL, commit_sha TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('fewer','worse')), allowed_count REAL, run_id TEXT REFERENCES check_runs(id), why TEXT NOT NULL, change_id TEXT, allowed_by TEXT NOT NULL REFERENCES actors(id), allowed_ms INTEGER NOT NULL, CHECK((kind='fewer') = (allowed_count IS NOT NULL)), CHECK((kind='worse') = (run_id IS NOT NULL)), PRIMARY KEY(workspace_id, check_id, commit_sha, kind));
CREATE TABLE check_readings (run_id TEXT NOT NULL REFERENCES check_runs(id), workspace_id TEXT NOT NULL, check_id TEXT NOT NULL, result TEXT NOT NULL CHECK(result IN ('passed','failed','measured')), value REAL, words TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '{}', piece_id TEXT REFERENCES pipeline_pieces(id), fix_topic_id TEXT REFERENCES topics(id), PRIMARY KEY(run_id, check_id));
CREATE TABLE check_runs (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES outcome_targets(workspace_id), commit_sha TEXT, source TEXT NOT NULL CHECK(source IN ('release-check','skill-check','reported')), started_ms INTEGER NOT NULL, finished_ms INTEGER NOT NULL, tools TEXT NOT NULL, steps TEXT NOT NULL DEFAULT '[]', note TEXT NOT NULL DEFAULT '', base_for_commit TEXT, trial_of TEXT, without TEXT, recorded_by TEXT NOT NULL REFERENCES actors(id), CHECK((trial_of IS NULL) = (without IS NULL)), CHECK(base_for_commit IS NULL OR trial_of IS NULL));
CREATE TABLE color_choices (actor_id TEXT NOT NULL REFERENCES actors(id), subject_id TEXT NOT NULL REFERENCES actors(id), color TEXT, revision INTEGER NOT NULL CHECK(revision>0), PRIMARY KEY(actor_id,subject_id));
CREATE TABLE conversation_items (message_id TEXT PRIMARY KEY REFERENCES messages(id), settled INTEGER NOT NULL DEFAULT 0 CHECK(settled IN (0,1)));
CREATE TABLE conversation_takes (id INTEGER PRIMARY KEY AUTOINCREMENT, item_id TEXT NOT NULL REFERENCES conversation_items(message_id), kind TEXT NOT NULL CHECK(kind IN ('answer','topic','pipeline')), ref TEXT NOT NULL, added INTEGER NOT NULL DEFAULT 0, part INTEGER NOT NULL DEFAULT 0, actor_id TEXT NOT NULL REFERENCES actors(id), at_ms INTEGER NOT NULL);
CREATE TABLE conversation_waits (ask_id TEXT NOT NULL REFERENCES messages(id), actor_id TEXT NOT NULL REFERENCES actors(id), PRIMARY KEY(ask_id,actor_id));
CREATE TABLE deliveries (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, message_id TEXT NOT NULL REFERENCES messages(id), recipient_id TEXT NOT NULL REFERENCES actors(id), group_id INTEGER NOT NULL REFERENCES delivery_groups(id), state TEXT NOT NULL DEFAULT 'pending', topic_id TEXT, UNIQUE(message_id,recipient_id));
CREATE TABLE delivery_groups (id INTEGER PRIMARY KEY AUTOINCREMENT, recipient_id TEXT NOT NULL REFERENCES actors(id), kind TEXT NOT NULL, topic_id TEXT NOT NULL, participant_epoch INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1, pending_count INTEGER NOT NULL DEFAULT 0 CHECK(pending_count>=0), first_pending_seq INTEGER, UNIQUE(recipient_id,kind,topic_id,participant_epoch));
CREATE TABLE delivery_reasons (delivery_id TEXT NOT NULL REFERENCES deliveries(id), reason TEXT NOT NULL, topic_id TEXT NOT NULL REFERENCES topics(id), participant_epoch INTEGER, PRIMARY KEY(delivery_id,reason));
CREATE TABLE drafts (id TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES actors(id), source_key TEXT NOT NULL, topic_id TEXT NOT NULL, revision INTEGER NOT NULL, generation TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(actor_id,id), UNIQUE(actor_id,source_key,topic_id));
CREATE TABLE found_problems (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), what TEXT NOT NULL CHECK(length(what) BETWEEN 1 AND 500), kind TEXT NOT NULL CHECK(kind IN ('defect','design_miss')), found_by TEXT NOT NULL REFERENCES actors(id), message_id TEXT REFERENCES messages(id), note TEXT, found_ms INTEGER NOT NULL, cover_item INTEGER, cover_words TEXT NOT NULL DEFAULT '', cover_test TEXT, closed_ms INTEGER, closed_commit TEXT, closed_proof TEXT, version INTEGER NOT NULL, CHECK((message_id IS NOT NULL) + (note IS NOT NULL) = 1));
CREATE TABLE hosted_children (id TEXT PRIMARY KEY, runner_token TEXT NOT NULL, codex_home TEXT NOT NULL, pid INTEGER NOT NULL, started_at TEXT NOT NULL, user_agent TEXT, spawned_ms INTEGER NOT NULL, exited_ms INTEGER, exit_status INTEGER, cleanup TEXT CHECK(cleanup IN ('confirmed','unconfirmed')));
CREATE TABLE hosted_turn_topics (attempt_id TEXT NOT NULL REFERENCES wake_attempts(id), topic_id TEXT NOT NULL REFERENCES topics(id), PRIMARY KEY(attempt_id,topic_id));
CREATE TABLE hosted_turns (attempt_id TEXT PRIMARY KEY REFERENCES wake_attempts(id), recipient_id TEXT NOT NULL REFERENCES actors(id), thread_id TEXT NOT NULL, turn_id TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('start','steer')), client_id TEXT NOT NULL, announced_seq INTEGER NOT NULL, handed_ms INTEGER NOT NULL, seen_ms INTEGER, final_status TEXT CHECK(final_status IN ('completed','interrupted','failed','lost')), error_code TEXT, finished_ms INTEGER, input_tokens INTEGER, cached_input_tokens INTEGER, output_tokens INTEGER, reasoning_output_tokens INTEGER, cli_calls INTEGER);
CREATE TABLE media_intents (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES actors(id), revision INTEGER NOT NULL, state TEXT NOT NULL, publish_operation_id TEXT NOT NULL, authority_id TEXT NOT NULL, authority_epoch TEXT NOT NULL, name TEXT NOT NULL, content_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, blob_key TEXT NOT NULL UNIQUE, inline INTEGER NOT NULL DEFAULT 0, UNIQUE(actor_id,publish_operation_id));
CREATE TABLE memory_items (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, scope_kind TEXT NOT NULL, scope_id TEXT NOT NULL, creator_id TEXT NOT NULL REFERENCES actors(id), current_revision INTEGER NOT NULL);
CREATE TABLE memory_notebooks (scope_kind TEXT NOT NULL, scope_id TEXT NOT NULL, version INTEGER NOT NULL, PRIMARY KEY(scope_kind,scope_id));
CREATE TABLE memory_reads (actor_id TEXT NOT NULL REFERENCES actors(id), item_id TEXT NOT NULL REFERENCES memory_items(id), revision INTEGER NOT NULL CHECK(revision>0), PRIMARY KEY(actor_id,item_id));
CREATE TABLE memory_revisions (item_id TEXT NOT NULL REFERENCES memory_items(id), revision INTEGER NOT NULL, author_id TEXT NOT NULL REFERENCES actors(id), operation_id TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, attachments TEXT NOT NULL, refs TEXT NOT NULL, PRIMARY KEY(item_id,revision), UNIQUE(author_id,operation_id));
CREATE TABLE message_addressees (topic_id TEXT NOT NULL REFERENCES topics(id), actor_id TEXT NOT NULL REFERENCES actors(id), seq INTEGER NOT NULL REFERENCES messages(seq), PRIMARY KEY(topic_id,actor_id,seq));
CREATE TABLE message_marks (actor_id TEXT NOT NULL REFERENCES actors(id), message_id TEXT NOT NULL REFERENCES messages(id), topic_id TEXT NOT NULL REFERENCES topics(id), seq INTEGER NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), PRIMARY KEY(actor_id,message_id));
CREATE TABLE message_reactions (actor_id TEXT NOT NULL REFERENCES actors(id), message_id TEXT NOT NULL REFERENCES messages(id), kind TEXT NOT NULL CHECK(kind IN ('thumb','answer')), topic_id TEXT NOT NULL REFERENCES topics(id), value TEXT CHECK(value IS NULL OR value IN ('up','yes','no')), at_ms INTEGER NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), PRIMARY KEY(actor_id,message_id,kind));
CREATE TABLE message_subjects (message_id TEXT NOT NULL REFERENCES messages(id), workspace_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('item','check')), ref TEXT NOT NULL, PRIMARY KEY(message_id, kind, ref));
CREATE TABLE messages (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, topic_id TEXT NOT NULL REFERENCES topics(id), author_id TEXT NOT NULL REFERENCES actors(id), body TEXT NOT NULL, attachments TEXT NOT NULL, quotes TEXT NOT NULL, addressees TEXT NOT NULL, reply_to TEXT, exchange_id TEXT, operation_id TEXT NOT NULL, sent_ms INTEGER, intent TEXT CHECK(intent IN ('ask','tell')), private_to TEXT, about_id TEXT, go_ahead INTEGER NOT NULL DEFAULT 0 CHECK(go_ahead IN (0,1)), UNIQUE(author_id,operation_id));
CREATE TABLE metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE notes (id TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES actors(id), source_key TEXT NOT NULL, revision INTEGER NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(actor_id,id), UNIQUE(actor_id,source_key));
CREATE TABLE openings (id TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES actors(id), workspace_id TEXT NOT NULL REFERENCES workspaces(id), topic_id TEXT NOT NULL UNIQUE, revision INTEGER NOT NULL, state TEXT NOT NULL CHECK (state IN ('open','published','discarded')), payload TEXT NOT NULL, publish_operation_id TEXT, message_id TEXT REFERENCES messages(id), PRIMARY KEY(actor_id,id));
CREATE TABLE operations (actor_id TEXT NOT NULL REFERENCES actors(id), id TEXT NOT NULL, fingerprint TEXT NOT NULL, kind TEXT NOT NULL, outcome TEXT NOT NULL, PRIMARY KEY(actor_id,id));
CREATE TABLE outcome_checks (workspace_id TEXT NOT NULL REFERENCES outcome_targets(workspace_id), check_id TEXT NOT NULL, revision INTEGER NOT NULL, group_name TEXT NOT NULL, position INTEGER NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('pass','measure')), source TEXT NOT NULL, unit TEXT NOT NULL DEFAULT '', better TEXT CHECK(better IN ('lower','higher')), target_value REAL, target_words TEXT NOT NULL DEFAULT '', tolerance REAL, repeats INTEGER NOT NULL DEFAULT 1 CHECK(repeats BETWEEN 1 AND 4), counted_since_ms INTEGER, explain TEXT NOT NULL DEFAULT '', pending_words TEXT NOT NULL DEFAULT '', record_memory_item_id TEXT REFERENCES memory_items(id), left_by_topic_id TEXT REFERENCES topics(id), retired_why TEXT, defined_by TEXT NOT NULL REFERENCES actors(id), defined_ms INTEGER NOT NULL, proves TEXT NOT NULL DEFAULT '', PRIMARY KEY(workspace_id, check_id, revision));
CREATE TABLE outcome_kinds (workspace_id TEXT NOT NULL REFERENCES workspaces(id), seq INTEGER NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('reach','keep')), origin TEXT NOT NULL CHECK(origin IN ('create','change')), set_by TEXT NOT NULL REFERENCES actors(id), set_ms INTEGER NOT NULL, PRIMARY KEY(workspace_id, seq));
CREATE TABLE outcome_reached (workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id), words TEXT NOT NULL CHECK(length(trim(words)) BETWEEN 1 AND 500), unmet TEXT NOT NULL DEFAULT '[]', reached_by TEXT NOT NULL REFERENCES actors(id), reached_ms INTEGER NOT NULL);
CREATE TABLE outcome_target_revisions (workspace_id TEXT NOT NULL REFERENCES outcome_targets(workspace_id), revision INTEGER NOT NULL, text TEXT NOT NULL, origin_note TEXT NOT NULL DEFAULT '', proposed_by TEXT NOT NULL REFERENCES actors(id), proposed_ms INTEGER NOT NULL, ask_message_id TEXT REFERENCES messages(id), outcome TEXT CHECK(outcome IN ('accepted','declined')), settled_by TEXT REFERENCES actors(id), settled_ms INTEGER, PRIMARY KEY(workspace_id, revision));
CREATE TABLE outcome_targets (workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id), version INTEGER NOT NULL);
CREATE TABLE outline_orders (actor_id TEXT NOT NULL REFERENCES actors(id), within TEXT NOT NULL, ids TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), PRIMARY KEY(actor_id,within));
CREATE TABLE pipeline_done_topics (topic_id TEXT PRIMARY KEY REFERENCES topics(id), workspace_id TEXT NOT NULL, release INTEGER NOT NULL);
CREATE TABLE pipeline_events (seq INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL, number INTEGER, kind TEXT NOT NULL CHECK(kind IN ('added','edited','moved','stages','configured')), by TEXT NOT NULL REFERENCES actors(id), ms INTEGER NOT NULL, payload TEXT NOT NULL);
CREATE TABLE pipeline_facts (seq INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL REFERENCES pipelines(workspace_id), kind TEXT NOT NULL CHECK(kind IN ('ships','start','combine','drop','finish','record')), ms INTEGER NOT NULL, by TEXT REFERENCES actors(id), payload TEXT NOT NULL);
CREATE TABLE pipeline_item_sources (workspace_id TEXT NOT NULL, number INTEGER NOT NULL, position INTEGER NOT NULL, message_id TEXT REFERENCES messages(id), memory_item_id TEXT REFERENCES memory_items(id), note TEXT, added_by TEXT NOT NULL REFERENCES actors(id), added_ms INTEGER NOT NULL, CHECK((message_id IS NOT NULL) + (memory_item_id IS NOT NULL) + (note IS NOT NULL) = 1), PRIMARY KEY(workspace_id, number, position), FOREIGN KEY(workspace_id, number) REFERENCES pipeline_items(workspace_id, number));
CREATE TABLE pipeline_items (workspace_id TEXT NOT NULL REFERENCES pipelines(workspace_id), number INTEGER NOT NULL CHECK(number BETWEEN 1 AND 99999), title TEXT NOT NULL, description TEXT NOT NULL, size TEXT CHECK(size IN ('small','medium','large')), raised_by TEXT REFERENCES actors(id), raised_note TEXT NOT NULL DEFAULT '', section TEXT NOT NULL CHECK(section IN ('now','next','later','candidates','dropped')), candidate_group TEXT NOT NULL DEFAULT '', position INTEGER NOT NULL, needs TEXT NOT NULL DEFAULT '[]', finished_note TEXT NOT NULL DEFAULT '', gathering TEXT, version INTEGER NOT NULL, PRIMARY KEY(workspace_id, number));
CREATE TABLE pipeline_piece_members (piece_id TEXT NOT NULL REFERENCES pipeline_pieces(id), workspace_id TEXT NOT NULL, number INTEGER NOT NULL, left_ms INTEGER, left_reason TEXT CHECK(left_reason IN ('combined','dropped','returned')), PRIMARY KEY(piece_id, number));
CREATE TABLE pipeline_pieces (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES pipelines(workspace_id), kind TEXT NOT NULL CHECK(kind IN ('piece','release')), topic_id TEXT NOT NULL REFERENCES topics(id), release_number INTEGER, commit_sha TEXT, version INTEGER NOT NULL);
CREATE TABLE pipeline_stage_entries (seq INTEGER PRIMARY KEY AUTOINCREMENT, piece_id TEXT NOT NULL REFERENCES pipeline_pieces(id), workspace_id TEXT NOT NULL, stage_id TEXT NOT NULL, round INTEGER NOT NULL CHECK(round >= 1), size TEXT, entered_ms INTEGER NOT NULL, entered_by TEXT NOT NULL REFERENCES actors(id), ask_message_id TEXT REFERENCES messages(id), note TEXT NOT NULL DEFAULT '', progress TEXT, left_ms INTEGER, left_outcome TEXT CHECK(left_outcome IN ('approved','sent back','passed','held','shipped','done','combined','dropped')), left_note TEXT NOT NULL DEFAULT '', left_by TEXT REFERENCES actors(id));
CREATE TABLE pipeline_stages (workspace_id TEXT NOT NULL REFERENCES pipelines(workspace_id), stage_id TEXT NOT NULL, position INTEGER, name TEXT NOT NULL, done_when TEXT NOT NULL, gate TEXT NOT NULL, rounds TEXT NOT NULL CHECK(rounds IN ('none','together','split')), scope TEXT NOT NULL CHECK(scope IN ('piece','release')), added_note TEXT NOT NULL DEFAULT '', PRIMARY KEY(workspace_id, stage_id));
CREATE TABLE pipelines (workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id), enabled INTEGER NOT NULL CHECK(enabled IN (0,1)), title TEXT NOT NULL, unit_one TEXT NOT NULL, unit_many TEXT NOT NULL, sized INTEGER NOT NULL CHECK(sized IN (0,1)), ships_in_releases INTEGER NOT NULL CHECK(ships_in_releases IN (0,1)), section_words TEXT NOT NULL, version INTEGER NOT NULL);
CREATE TABLE recipient_schedule (recipient_id TEXT PRIMARY KEY REFERENCES actors(id), enabled INTEGER NOT NULL, pending_count INTEGER NOT NULL DEFAULT 0 CHECK(pending_count>=0), wake_generation INTEGER NOT NULL DEFAULT 0, last_seq INTEGER NOT NULL DEFAULT 0, next_due_ms INTEGER, retry_count INTEGER NOT NULL DEFAULT 0, captured_generation INTEGER, captured_seq INTEGER, claim_token TEXT, claim_until_ms INTEGER, handed_seq INTEGER, unanswered_wakes INTEGER NOT NULL DEFAULT 0, unanswered_since_ms INTEGER, named_seq INTEGER);
CREATE TABLE release_notes (release_label TEXT NOT NULL, position INTEGER NOT NULL, text TEXT NOT NULL, PRIMARY KEY(release_label, position));
CREATE TABLE releases (number INTEGER PRIMARY KEY CHECK(number>0), commit_sha TEXT NOT NULL UNIQUE, previous_sha TEXT, deployed_at TEXT NOT NULL, deployed_ms INTEGER NOT NULL, items TEXT NOT NULL, measurements TEXT, source TEXT NOT NULL CHECK(source IN ('deploy','backfill')), evidence TEXT, recorded_ms INTEGER NOT NULL);
CREATE TABLE reply_horizons (topic_id TEXT NOT NULL REFERENCES topics(id), actor_id TEXT NOT NULL REFERENCES actors(id), seq INTEGER NOT NULL, PRIMARY KEY(topic_id,actor_id));
CREATE TABLE runner_prior (id INTEGER PRIMARY KEY CHECK(id=1), state TEXT NOT NULL, reason TEXT, ended_ms INTEGER);
CREATE TABLE runner_state (id INTEGER PRIMARY KEY CHECK(id=1), state TEXT NOT NULL, version INTEGER NOT NULL, runner_token TEXT, runner_id TEXT, guard_generation TEXT, lease_until_ms INTEGER, reason_code TEXT, runner_pid INTEGER, runner_started_ms INTEGER, child_pid INTEGER, child_started_at TEXT, child_claim_token TEXT, ended_ms INTEGER);
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE submissions (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES actors(id), source_key TEXT NOT NULL, topic_id TEXT NOT NULL, prepare_operation_id TEXT NOT NULL, send_operation_id TEXT NOT NULL, send_kind TEXT NOT NULL, authority_id TEXT NOT NULL, authority_epoch TEXT NOT NULL, metadata TEXT NOT NULL, snapshot TEXT NOT NULL, UNIQUE(actor_id,id), UNIQUE(actor_id,send_operation_id));
CREATE TABLE topic_participants (topic_id TEXT NOT NULL REFERENCES topics(id), actor_id TEXT NOT NULL REFERENCES actors(id), active INTEGER NOT NULL, epoch INTEGER NOT NULL, responsibility TEXT NOT NULL DEFAULT '', responsibility_revision INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(topic_id,actor_id));
CREATE TABLE topic_summaries (topic_id TEXT PRIMARY KEY REFERENCES topics(id), message_count INTEGER NOT NULL, latest_message_id TEXT REFERENCES messages(id), other_message_id TEXT);
CREATE TABLE topic_turns (topic_id TEXT PRIMARY KEY REFERENCES topics(id), turn_ms INTEGER NOT NULL, turn_by TEXT NOT NULL REFERENCES actors(id), other_ms INTEGER, other_by TEXT);
CREATE TABLE topic_waiting (topic_id TEXT NOT NULL REFERENCES topics(id), actor_id TEXT NOT NULL REFERENCES actors(id), state_ms INTEGER, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), said INTEGER NOT NULL DEFAULT 1 CHECK(said IN (0,1)), ask_message_id TEXT REFERENCES messages(id), PRIMARY KEY(topic_id,actor_id));
CREATE TABLE topics (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), title TEXT NOT NULL, creator_id TEXT NOT NULL REFERENCES actors(id), version INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'active' CHECK(state IN ('active','waiting','review','done')), archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), state_note TEXT NOT NULL DEFAULT '', state_by TEXT REFERENCES actors(id), state_ms INTEGER, activity_ms INTEGER NOT NULL DEFAULT 0, state_message_id TEXT REFERENCES messages(id), source_message_id TEXT REFERENCES messages(id), kind TEXT NOT NULL DEFAULT 'topic' CHECK(kind IN ('topic','conversation')), replaced_by TEXT);
CREATE TABLE wake_attempts (id TEXT PRIMARY KEY, claim_token TEXT NOT NULL UNIQUE, runner_token TEXT NOT NULL, recipient_id TEXT NOT NULL REFERENCES actors(id), wake_generation INTEGER NOT NULL, captured_seq INTEGER NOT NULL, started_ms INTEGER NOT NULL, lease_until_ms INTEGER NOT NULL, handed_seq INTEGER);
CREATE TABLE wake_facts (recipient_id TEXT PRIMARY KEY REFERENCES actors(id), reached_ms INTEGER, failed_wakes INTEGER NOT NULL DEFAULT 0, failing_since_ms INTEGER, failed_ms INTEGER, failed_outcome TEXT, failed_reason TEXT, unanswered_wakes INTEGER NOT NULL DEFAULT 0, unanswered_since_ms INTEGER, acted_ms INTEGER);
CREATE TABLE wake_results (attempt_id TEXT PRIMARY KEY REFERENCES wake_attempts(id), outcome TEXT NOT NULL, finished_ms INTEGER NOT NULL);
CREATE TABLE wake_turns (thread_id TEXT NOT NULL, turn_id TEXT NOT NULL, recipient_id TEXT NOT NULL REFERENCES actors(id), began_ms INTEGER NOT NULL, handed_ms INTEGER NOT NULL, carried INTEGER NOT NULL, acted INTEGER NOT NULL, PRIMARY KEY(thread_id,turn_id));
CREATE TABLE workspace_members (workspace_id TEXT NOT NULL REFERENCES workspaces(id), actor_id TEXT NOT NULL REFERENCES actors(id), PRIMARY KEY(workspace_id,actor_id));
CREATE TABLE workspaces (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES actors(id), title TEXT NOT NULL, purpose TEXT NOT NULL, coordinator_id TEXT REFERENCES actors(id), version INTEGER NOT NULL);
CREATE TRIGGER definitions_stay_d BEFORE DELETE ON outcome_checks BEGIN SELECT RAISE(ABORT, 'a definition keeps its words'); END;
CREATE TRIGGER definitions_stay_u BEFORE UPDATE ON outcome_checks BEGIN SELECT RAISE(ABORT, 'a definition keeps its words'); END;
CREATE TRIGGER delivery_topic_required BEFORE INSERT ON deliveries WHEN NEW.topic_id IS NULL BEGIN SELECT RAISE(ABORT, 'a delivery names its topic'); END;
CREATE TRIGGER entries_enter_on_an_ask BEFORE INSERT ON pipeline_stage_entries WHEN (SELECT json_extract(gate,'$.owner') FROM pipeline_stages WHERE workspace_id=NEW.workspace_id AND stage_id=NEW.stage_id) AND NOT EXISTS (SELECT 1 FROM messages m, pipeline_pieces p, workspaces w WHERE m.id=NEW.ask_message_id AND p.id=NEW.piece_id AND w.id=p.workspace_id AND m.topic_id=p.topic_id AND m.author_id=NEW.entered_by AND m.intent='ask' AND EXISTS (SELECT 1 FROM json_each(m.addressees) a WHERE a.value=w.owner_id)) BEGIN SELECT RAISE(ABORT, 'ASK_REQUIRED'); END;
CREATE TRIGGER entries_keep_their_past BEFORE UPDATE ON pipeline_stage_entries WHEN (OLD.left_ms IS NOT NULL AND NOT (NEW.left_ms IS OLD.left_ms AND NEW.left_by IS OLD.left_by AND NEW.note IS OLD.note AND NEW.progress IS OLD.progress AND NOT EXISTS (SELECT 1 FROM pipeline_stage_entries e WHERE e.piece_id=OLD.piece_id AND e.seq>OLD.seq) AND (((SELECT kind FROM pipeline_pieces WHERE id=OLD.piece_id)='piece' AND OLD.left_outcome IN ('dropped','shipped') AND NEW.left_outcome='shipped') OR ((SELECT kind FROM pipeline_pieces WHERE id=OLD.piece_id)='release' AND OLD.left_outcome IN ('dropped','held') AND NEW.left_outcome IN ('held','shipped'))))) OR NEW.seq IS NOT OLD.seq OR NEW.piece_id IS NOT OLD.piece_id OR NEW.stage_id IS NOT OLD.stage_id OR NEW.round IS NOT OLD.round OR NEW.size IS NOT OLD.size OR NEW.entered_ms IS NOT OLD.entered_ms OR NEW.entered_by IS NOT OLD.entered_by OR NEW.ask_message_id IS NOT OLD.ask_message_id BEGIN SELECT RAISE(ABORT, 'a stage entry keeps its past'); END;
CREATE TRIGGER entries_leave_by_the_owner BEFORE UPDATE OF left_ms ON pipeline_stage_entries WHEN NEW.left_ms IS NOT NULL AND (SELECT json_extract(gate,'$.owner') FROM pipeline_stages WHERE workspace_id=OLD.workspace_id AND stage_id=OLD.stage_id) AND NEW.left_by IS NOT (SELECT owner_id FROM workspaces WHERE id=OLD.workspace_id) AND NOT (NEW.left_by IS NULL AND EXISTS (SELECT 1 FROM pipeline_facts f WHERE f.workspace_id=OLD.workspace_id AND f.ms=NEW.left_ms AND (f.kind='record' OR (f.kind='ships' AND json_extract(f.payload,'$.on'))))) BEGIN SELECT RAISE(ABORT, 'STAGE_GATED'); END;
CREATE TRIGGER entries_stay BEFORE DELETE ON pipeline_stage_entries BEGIN SELECT RAISE(ABORT, 'a stage entry keeps its past'); END;
CREATE TRIGGER events_stay_d BEFORE DELETE ON pipeline_events BEGIN SELECT RAISE(ABORT, 'an event keeps its past'); END;
CREATE TRIGGER events_stay_u BEFORE UPDATE ON pipeline_events BEGIN SELECT RAISE(ABORT, 'an event keeps its past'); END;
CREATE TRIGGER facts_stay_d BEFORE DELETE ON pipeline_facts BEGIN SELECT RAISE(ABORT, 'a fact keeps its past'); END;
CREATE TRIGGER facts_stay_u BEFORE UPDATE ON pipeline_facts BEGIN SELECT RAISE(ABORT, 'a fact keeps its past'); END;
CREATE TRIGGER immutable_hosted_children_delete BEFORE DELETE ON hosted_children BEGIN SELECT RAISE(ABORT,'immutable hosted_children'); END;
CREATE TRIGGER immutable_hosted_turns_delete BEFORE DELETE ON hosted_turns BEGIN SELECT RAISE(ABORT,'immutable hosted_turns'); END;
CREATE TRIGGER immutable_media_delete BEFORE DELETE ON media_intents BEGIN SELECT RAISE(ABORT, 'immutable media intent'); END;
CREATE TRIGGER immutable_media_intent BEFORE UPDATE ON media_intents WHEN OLD.state='ready' OR NEW.id!=OLD.id OR NEW.actor_id!=OLD.actor_id OR NEW.publish_operation_id!=OLD.publish_operation_id OR NEW.authority_id!=OLD.authority_id OR NEW.authority_epoch!=OLD.authority_epoch OR NEW.name!=OLD.name OR NEW.content_type!=OLD.content_type OR NEW.size_bytes!=OLD.size_bytes OR NEW.sha256!=OLD.sha256 OR NEW.blob_key!=OLD.blob_key BEGIN SELECT RAISE(ABORT, 'immutable media intent'); END;
CREATE TRIGGER immutable_memory_identity BEFORE UPDATE ON memory_items WHEN NEW.seq!=OLD.seq OR NEW.id!=OLD.id OR NEW.scope_kind!=OLD.scope_kind OR NEW.scope_id!=OLD.scope_id OR NEW.creator_id!=OLD.creator_id BEGIN SELECT RAISE(ABORT, 'immutable Notebook identity'); END;
CREATE TRIGGER immutable_memory_item_delete BEFORE DELETE ON memory_items BEGIN SELECT RAISE(ABORT, 'immutable Notebook identity'); END;
CREATE TRIGGER immutable_memory_revision_delete BEFORE DELETE ON memory_revisions BEGIN SELECT RAISE(ABORT, 'immutable Notebook revision'); END;
CREATE TRIGGER immutable_memory_revision_update BEFORE UPDATE ON memory_revisions BEGIN SELECT RAISE(ABORT, 'immutable Notebook revision'); END;
CREATE TRIGGER immutable_messages_delete BEFORE DELETE ON messages BEGIN SELECT RAISE(ABORT, 'immutable message'); END;
CREATE TRIGGER immutable_messages_update BEFORE UPDATE ON messages BEGIN SELECT RAISE(ABORT, 'immutable message'); END;
CREATE TRIGGER immutable_operations_delete BEFORE DELETE ON operations BEGIN SELECT RAISE(ABORT, 'immutable operation'); END;
CREATE TRIGGER immutable_operations_update BEFORE UPDATE ON operations BEGIN SELECT RAISE(ABORT, 'immutable operation'); END;
CREATE TRIGGER immutable_releases_delete BEFORE DELETE ON releases BEGIN SELECT RAISE(ABORT, 'immutable release'); END;
CREATE TRIGGER immutable_releases_update BEFORE UPDATE ON releases BEGIN SELECT RAISE(ABORT, 'immutable release'); END;
CREATE TRIGGER immutable_submissions_delete BEFORE DELETE ON submissions BEGIN SELECT RAISE(ABORT, 'immutable submission'); END;
CREATE TRIGGER immutable_submissions_update BEFORE UPDATE ON submissions BEGIN SELECT RAISE(ABORT, 'immutable submission'); END;
CREATE TRIGGER immutable_takes_delete BEFORE DELETE ON conversation_takes BEGIN SELECT RAISE(ABORT, 'immutable take'); END;
CREATE TRIGGER immutable_takes_update BEFORE UPDATE ON conversation_takes BEGIN SELECT RAISE(ABORT, 'immutable take'); END;
CREATE TRIGGER immutable_wake_attempt_delete BEFORE DELETE ON wake_attempts BEGIN SELECT RAISE(ABORT,'immutable wake attempt'); END;
CREATE TRIGGER immutable_wake_attempt_update BEFORE UPDATE ON wake_attempts BEGIN SELECT RAISE(ABORT,'immutable wake attempt'); END;
CREATE TRIGGER immutable_wake_result_delete BEFORE DELETE ON wake_results BEGIN SELECT RAISE(ABORT,'immutable wake result'); END;
CREATE TRIGGER immutable_wake_result_update BEFORE UPDATE ON wake_results BEGIN SELECT RAISE(ABORT,'immutable wake result'); END;
CREATE TRIGGER items_stay BEFORE DELETE ON pipeline_items BEGIN SELECT RAISE(ABORT, 'an item keeps its number'); END;
CREATE TRIGGER kept_allowance_d BEFORE DELETE ON check_allowances BEGIN SELECT RAISE(ABORT, 'an allowance stays'); END;
CREATE TRIGGER kept_allowance_u BEFORE UPDATE ON check_allowances BEGIN SELECT RAISE(ABORT, 'an allowance stays'); END;
CREATE TRIGGER kinds_start_first BEFORE INSERT ON outcome_kinds WHEN NEW.origin = 'create' AND NEW.seq <> 1 BEGIN SELECT RAISE(ABORT, 'a start record is the first row'); END;
CREATE TRIGGER kinds_stay_d BEFORE DELETE ON outcome_kinds BEGIN SELECT RAISE(ABORT, 'a kind keeps its past'); END;
CREATE TRIGGER kinds_stay_u BEFORE UPDATE ON outcome_kinds BEGIN SELECT RAISE(ABORT, 'a kind keeps its past'); END;
CREATE TRIGGER problem_keeps_what_was_found BEFORE UPDATE ON found_problems WHEN NEW.what IS NOT OLD.what OR NEW.kind IS NOT OLD.kind OR NEW.found_by IS NOT OLD.found_by OR NEW.message_id IS NOT OLD.message_id OR NEW.note IS NOT OLD.note OR NEW.found_ms IS NOT OLD.found_ms OR OLD.closed_ms IS NOT NULL BEGIN SELECT RAISE(ABORT, 'a found problem keeps what was found'); END;
CREATE TRIGGER problems_stay BEFORE DELETE ON found_problems BEGIN SELECT RAISE(ABORT, 'a found problem keeps what was found'); END;
CREATE TRIGGER reached_stays_d BEFORE DELETE ON outcome_reached BEGIN SELECT RAISE(ABORT, 'reached is final'); END;
CREATE TRIGGER reached_stays_u BEFORE UPDATE ON outcome_reached BEGIN SELECT RAISE(ABORT, 'reached is final'); END;
CREATE TRIGGER readings_stay_d BEFORE DELETE ON check_readings BEGIN SELECT RAISE(ABORT, 'a reading keeps what it measured'); END;
CREATE TRIGGER readings_stay_u BEFORE UPDATE ON check_readings BEGIN SELECT RAISE(ABORT, 'a reading keeps what it measured'); END;
CREATE TRIGGER recipient_enabled AFTER UPDATE OF enabled ON actors BEGIN UPDATE recipient_schedule SET enabled=NEW.enabled WHERE recipient_id=NEW.id; END;
CREATE TRIGGER release_notes_stay_d BEFORE DELETE ON release_notes BEGIN SELECT RAISE(ABORT, 'a release note keeps its words'); END;
CREATE TRIGGER release_notes_stay_u BEFORE UPDATE ON release_notes BEGIN SELECT RAISE(ABORT, 'a release note keeps its words'); END;
CREATE TRIGGER runs_stay_d BEFORE DELETE ON check_runs BEGIN SELECT RAISE(ABORT, 'a run keeps what it measured'); END;
CREATE TRIGGER runs_stay_u BEFORE UPDATE ON check_runs BEGIN SELECT RAISE(ABORT, 'a run keeps what it measured'); END;
CREATE TRIGGER sources_stay BEFORE DELETE ON pipeline_item_sources BEGIN SELECT RAISE(ABORT, 'an item keeps where it came from'); END;
CREATE TRIGGER subjects_stay BEFORE DELETE ON message_subjects BEGIN SELECT RAISE(ABORT, 'a message keeps its subjects'); END;
CREATE TRIGGER target_revisions_stay BEFORE DELETE ON outcome_target_revisions BEGIN SELECT RAISE(ABORT, 'a target keeps its words'); END;
CREATE TRIGGER target_words_stay BEFORE UPDATE ON outcome_target_revisions WHEN OLD.outcome IS NOT NULL OR NEW.text IS NOT OLD.text OR NEW.proposed_by IS NOT OLD.proposed_by OR NEW.proposed_ms IS NOT OLD.proposed_ms OR NEW.ask_message_id IS NOT OLD.ask_message_id BEGIN SELECT RAISE(ABORT, 'a target keeps its words'); END;
CREATE TRIGGER whisper_shape BEFORE INSERT ON messages WHEN NEW.private_to IS NOT NULL AND (NEW.addressees <> json_array(NEW.private_to) OR NEW.intent IS NOT NULL OR NEW.private_to = NEW.author_id) BEGIN SELECT RAISE(ABORT, 'whisper shape'); END;
CREATE TRIGGER write_once_hosted_children BEFORE UPDATE ON hosted_children WHEN (OLD.id IS NOT NULL AND NEW.id IS NOT OLD.id) OR (OLD.runner_token IS NOT NULL AND NEW.runner_token IS NOT OLD.runner_token) OR (OLD.codex_home IS NOT NULL AND NEW.codex_home IS NOT OLD.codex_home) OR (OLD.pid IS NOT NULL AND NEW.pid IS NOT OLD.pid) OR (OLD.started_at IS NOT NULL AND NEW.started_at IS NOT OLD.started_at) OR (OLD.user_agent IS NOT NULL AND NEW.user_agent IS NOT OLD.user_agent) OR (OLD.spawned_ms IS NOT NULL AND NEW.spawned_ms IS NOT OLD.spawned_ms) OR (OLD.exited_ms IS NOT NULL AND NEW.exited_ms IS NOT OLD.exited_ms) OR (OLD.exit_status IS NOT NULL AND NEW.exit_status IS NOT OLD.exit_status) OR (OLD.cleanup IS NOT NULL AND NEW.cleanup IS NOT OLD.cleanup) BEGIN SELECT RAISE(ABORT,'write-once hosted_children'); END;
CREATE TRIGGER write_once_hosted_turns BEFORE UPDATE ON hosted_turns WHEN (OLD.attempt_id IS NOT NULL AND NEW.attempt_id IS NOT OLD.attempt_id) OR (OLD.recipient_id IS NOT NULL AND NEW.recipient_id IS NOT OLD.recipient_id) OR (OLD.thread_id IS NOT NULL AND NEW.thread_id IS NOT OLD.thread_id) OR (OLD.turn_id IS NOT NULL AND NEW.turn_id IS NOT OLD.turn_id) OR (OLD.mode IS NOT NULL AND NEW.mode IS NOT OLD.mode) OR (OLD.client_id IS NOT NULL AND NEW.client_id IS NOT OLD.client_id) OR (OLD.announced_seq IS NOT NULL AND NEW.announced_seq IS NOT OLD.announced_seq) OR (OLD.handed_ms IS NOT NULL AND NEW.handed_ms IS NOT OLD.handed_ms) OR (OLD.seen_ms IS NOT NULL AND NEW.seen_ms IS NOT OLD.seen_ms) OR (OLD.final_status IS NOT NULL AND NEW.final_status IS NOT OLD.final_status) OR (OLD.error_code IS NOT NULL AND NEW.error_code IS NOT OLD.error_code) OR (OLD.finished_ms IS NOT NULL AND NEW.finished_ms IS NOT OLD.finished_ms) OR (OLD.input_tokens IS NOT NULL AND NEW.input_tokens IS NOT OLD.input_tokens) OR (OLD.cached_input_tokens IS NOT NULL AND NEW.cached_input_tokens IS NOT OLD.cached_input_tokens) OR (OLD.output_tokens IS NOT NULL AND NEW.output_tokens IS NOT OLD.output_tokens) OR (OLD.reasoning_output_tokens IS NOT NULL AND NEW.reasoning_output_tokens IS NOT OLD.reasoning_output_tokens) OR (OLD.cli_calls IS NOT NULL AND NEW.cli_calls IS NOT OLD.cli_calls) BEGIN SELECT RAISE(ABORT,'write-once hosted_turns'); END;
CREATE UNIQUE INDEX kinds_one_start ON outcome_kinds(workspace_id) WHERE origin = 'create';
CREATE UNIQUE INDEX one_open_entry ON pipeline_stage_entries(piece_id) WHERE left_ms IS NULL;
CREATE UNIQUE INDEX one_piece_per_item ON pipeline_piece_members(workspace_id, number) WHERE left_ms IS NULL;
CREATE UNIQUE INDEX one_release_pipeline ON pipelines(ships_in_releases) WHERE ships_in_releases=1;
CREATE UNIQUE INDEX outcome_conversation ON topics(workspace_id) WHERE kind = 'conversation';
